    const n = parseFloat(s);
    if (!Number.isFinite(n)) return null;

    if (s.endsWith('px')) return n;
    if (s.endsWith('pt')) return n * (96 / 72);

    if (s.endsWith('rem')) return n * 16;
    if (s.endsWith('em')) return n * 16;
    if (s.endsWith('%')) return (n / 100) * 16;

    return n;
